import random
import subprocess
import tempfile
from pathlib import Path
SAMPLE_IN = '1\n6 6 2\n...S..\n...#..\n.#....\n...#..\n...#..\n..#E#.\n'
SAMPLE_OUT = '7\n'
CASES = ['1\n6 6 2\n...S..\n...#..\n.#....\n...#..\n...#..\n..#E#.\n', '3\n4 5 7\nS....\n..#..\n....#\n....E\n5 5 9\nS....\n.#..#\n.....\n....#\n....E\n6 9 7\nS#....#.#\n....#.##.\n.....#.##\n.....#...\n...#..##.\n........E\n', '1\n4 6 3\nS.....\n.#....\n......\n.....E\n', '2\n8 5 10\nS#..#\n..#..\n.....\n....#\n.....\n..#..\n.#...\n....E\n6 9 9\nS#...#...\n...#....#\n......#..\n..#.#..##\n....#...#\n........E\n', '2\n9 7 3\nS...#..\n.......\n..#....\n......#\n.#..#..\n...#.##\n.##....\n...#.#.\n......E\n4 7 7\nS##....\n..###..\n....#.#\n......E\n', '2\n7 6 3\nS.#.#.\n..##..\n..#.#.\n......\n..##..\n......\n.....E\n8 9 5\nS#...#...\n.......#.\n..#.....#\n.#..#...#\n...#...#.\n.........\n...##...#\n........E\n', '2\n9 9 2\nS..#.#.#.\n.....#.#.\n.#.###.#.\n.#..#.#..\n..#......\n.#.#...#.\n.........\n.........\n........E\n4 4 7\nS#..\n...#\n....\n...E\n', '3\n4 8 5\nS...#...\n...#.#..\n...#..#.\n.......E\n8 5 9\nS.#.#\n.#...\n.....\n....#\n..#..\n...#.\n..#..\n....E\n6 9 5\nS......#.\n....###.#\n......#..\n....#.#..\n.......#.\n........E\n', '1\n6 6 7\nS.#.#.\n......\n.#....\n..##..\n.#...#\n.....E\n', '3\n5 4 6\nS...\n....\n....\n...#\n...E\n4 5 6\nS..#.\n.#...\n.....\n....E\n5 4 10\nS##.\n....\n....\n.#..\n...E\n', '1\n6 4 9\nS.#.\n...#\n.#..\n.###\n.###\n...E\n', '1\n7 7 2\nS..##.#\n....#..\n.......\n....#.#\n.#..#..\n......#\n......E\n', '1\n5 6 8\nS..###\n..#...\n......\n.#....\n.....E\n', '1\n9 9 4\nS.##.#...\n...##....\n.......#.\n.........\n.#..#....\n.........\n...#.##..\n.#....#..\n........E\n', '3\n6 7 10\nS.#..##\n.....#.\n..#...#\n.#.....\n.#...##\n......E\n9 9 4\nS........\n.#...#.#.\n.......##\n.#...#.#.\n.........\n.#..#....\n.#..#..#.\n.........\n........E\n8 7 5\nS...##.\n....#..\n.#.....\n...#...\n..#....\n...##.#\n.......\n......E\n', '3\n8 6 4\nS##.#.\n....#.\n..#...\n......\n......\n..#.##\n.##.#.\n.....E\n8 6 9\nS#....\n...#..\n......\n..#.#.\n.#....\n..#...\n......\n.....E\n8 4 3\nS...\n....\n...#\n..#.\n....\n.#.#\n...#\n...E\n', '1\n5 5 10\nS..#.\n.....\n..#..\n..#..\n....E\n', '3\n6 6 4\nS...#.\n......\n.#..#.\n..#..#\n......\n.....E\n6 7 10\nS.....#\n.##..#.\n..#.#..\n.....#.\n..#.#..\n......E\n4 4 9\nS...\n....\n....\n...E\n', '1\n4 9 2\nS.#....#.\n..##....#\n..#......\n........E\n', '1\n5 8 7\nS#.#....\n.#..#...\n..##....\n.#.#.###\n.......E\n']
REFERENCE_SOURCE = 'import sys\nfrom collections import deque\n\ndef solve():\n    input = sys.stdin.readline\n    T = int(input())\n    for _ in range(T):\n        R, C, K = map(int, input().split())\n        maze = [list(input().rstrip(\'\\n\')) for _ in range(R)]\n        \n        # Find S and E\n        for i in range(R):\n            for j in range(C):\n                if maze[i][j] == \'S\':\n                    sr, sc = i, j\n                elif maze[i][j] == \'E\':\n                    er, ec = i, j\n        \n        # dist[r][c][m] = minimum absolute time to reach (r,c) with time mod K == m\n        INF = 10**18\n        dist = [[[INF]*K for _ in range(C)] for __ in range(R)]\n        \n        dq = deque()\n        dist[sr][sc][0] = 0\n        dq.append((sr, sc, 0))  # at time 0\n        \n        ans = None\n        while dq:\n            r, c, m = dq.popleft()\n            t = dist[r][c][m]\n            # If we\'ve reached the exit, record and break (BFS ensures minimal time)\n            if (r, c) == (er, ec):\n                ans = t\n                break\n            \n            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):\n                nr, nc = r+dr, c+dc\n                nt = t + 1\n                nm = nt % K\n                if not (0 <= nr < R and 0 <= nc < C):\n                    continue\n                cell = maze[nr][nc]\n                # If it\'s a rock, only allowed if nt % K == 0\n                if cell == \'#\' and nm != 0:\n                    continue\n                # \'.\' or \'S\' or \'E\' always ok\n                if dist[nr][nc][nm] > nt:\n                    dist[nr][nc][nm] = nt\n                    dq.append((nr, nc, nm))\n        \n        if ans is None:\n            print("Oop!")\n        else:\n            print(ans)\n\n\nif __name__ == "__main__":\n    solve()\n'
assert CASES[0] == SAMPLE_IN
random.seed(4129)
def solve_reference(content):
    with tempfile.NamedTemporaryFile("w", suffix=".py", encoding="utf-8") as handle:
        handle.write(REFERENCE_SOURCE); handle.flush()
        result = subprocess.run(["python3", handle.name], input=content, text=True,
                                capture_output=True, timeout=5, check=True)
    return result.stdout
assert solve_reference(SAMPLE_IN).split() == SAMPLE_OUT.split()
root = Path(__file__).parent / "data"
for index in range(20):
    content = CASES[index]
    (root / f"{index}.in").write_text(content, encoding="utf-8")
    (root / f"{index}.out").write_text(solve_reference(content), encoding="utf-8")
